#include <stdlib.h>

#include "doubletime.h"
#include "erase.h"

#define ERASE_SECONDS 1.0
#define BLIND_HEIGHT 32

typedef void (*EraseEffect)(Display *dpy, Window w, GC gc, double ratio);

