    if (!st) {
      XClearWindow(dpy, w);
      return NULL;
    }
    const int pick = g_forced_effect >= 0 && g_forced_effect < EFFECT_COUNT
                         ? g_forced_effect
                         : (int)(random() % EFFECT_COUNT);
    st->effect = k_effects[pick];
    st->gc = XCreateGC(dpy, w, 0, NULL);
    return st;
  }

  const double now = double_time();
  if (!st->started) {
    st->started = 1;
    st->start = now;
