  UNITY_BEGIN();
  RUN_TEST(test_stopping_mid_wipe_frees_a_state_the_hack_never_frees);
  RUN_TEST(test_eraser_free_then_release_does_not_double_free);
  RUN_TEST(test_release_frees_every_live_state_on_the_display);

